import heapq
G={'A':[('B',1),('C',4)],'B':[('C',2),('D',5)],'C':[('D',1)],'D':[('E',3)],'E':[]}
dist={n:float('inf') for n in G}; dist['A']=0
pq=[(0,'A')]
while pq:
    d,u=heapq.heappop(pq)
    if d>dist[u]: continue
    for v,w in G[u]:
        if d+w<dist[v]:
            dist[v]=d+w; heapq.heappush(pq,(dist[v],v))
print(dist)  # A0 B1 C3 D4 E7

w=[1,3,4,5]; v=[1,4,5,7]; W=7; n=4
dp=[[0]*(W+1) for _ in range(n+1)]
for i in range(1,n+1):
    for c in range(W+1):
        dp[i][c]=dp[i-1][c]
        if w[i-1]<=c:
            dp[i][c]=max(dp[i][c], v[i-1]+dp[i-1][c-w[i-1]])
print('best value',dp[n][W])  # 9
# backtrack
c=W; take=[]
for i in range(n,0,-1):
    if dp[i][c]!=dp[i-1][c]:
        take.append(i-1); c-=w[i-1]
print('items',sorted(take))  # 1 and 2 -> (3,4)+(4,5)=9

import numpy as np
def F(v): x,y=v; return np.array([x*x+y*y-4, x*y-1])
def J(v): x,y=v; return np.array([[2*x,2*y],[y,x]])
v=np.array([2.0,1.0])
for k in range(6):
    dv=np.linalg.solve(J(v),-F(v))
    v=v+dv
    print(k,np.round(v,6),'residual',round(np.linalg.norm(F(v)),2e-1*0+9))

import numpy as np
def deriv(s):
    x,y,vx,vy=s; r=(x*x+y*y)**1.5
    return np.array([vx,vy,-x/r,-y/r])
s=np.array([1.,0.,0.,1.])   # circular orbit, period 2*pi
dt=0.01
def energy(s): x,y,vx,vy=s; return 0.5*(vx*vx+vy*vy)-1/np.hypot(x,y)
E0=energy(s)
for _ in range(int(2*np.pi/dt)):
    k1=deriv(s); k2=deriv(s+dt/2*k1); k3=deriv(s+dt/2*k2); k4=deriv(s+dt*k3)
    s=s+dt/6*(k1+2*k2+2*k3+k4)
print('pos',np.round(s[:2],4),'energy drift',round(energy(s)-E0,3e-1*0+8))

import heapq
W,H=4,4; walls={(1,1),(1,2),(2,1)}
def nbr(p):
    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
        q=(p[0]+dx,p[1]+dy)
        if 0<=q[0]<W and 0<=q[1]<H and q not in walls: yield q
h=lambda p:abs(3-p[0])+abs(3-p[1])
start,goal=(0,0),(3,3)
pq=[(h(start),0,start)]; g={start:0}; came={}
while pq:
    f,gc,u=heapq.heappop(pq)
    if u==goal: break
    for v in nbr(u):
        ng=gc+1
        if v not in g or ng<g[v]:
            g[v]=ng; came[v]=u; heapq.heappush(pq,(ng+h(v),ng,v))
print('path length',g[goal])  # 6
